    assert_eq!(candidate("zyxwvutsrqponmlkjihgfedcba", "azbycxdwevfugthsisrjrqponmlkjihgfedcba"), False);
    assert_eq!(candidate("abcdefghijklmnopqrstuvwxyz", "yz"), True);
    assert_eq!(candidate("zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz", "zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz"), True);
    assert_eq!(candidate("abcdefghijklmnopqrstuvwxyz", "st"), True);
}
